import{c as t,Q as o,j as a,m as s}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Loops: What Every AI Engineer Needs to Know in 2026","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-09-@sairahul1-555684.md","filePath":"research/tweets/2026-06-09-@sairahul1-555684.md","lastUpdated":1785909234000}'),p={name:"research/tweets/2026-06-09-@sairahul1-555684.md"};function n(r,e,i,l,h,d){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="loops-what-every-ai-engineer-needs-to-know-in-2026" tabindex="-1">Loops: What Every AI Engineer Needs to Know in 2026 <a class="header-anchor" href="#loops-what-every-ai-engineer-needs-to-know-in-2026" aria-label="Permalink to &quot;Loops: What Every AI Engineer Needs to Know in 2026&quot;">​</a></h1><p><strong>作者</strong>：Rahul (@sairahul1)<br><strong>發布時間</strong>：2026-06-09<br><strong>原始連結</strong>：<a href="https://x.com/sairahul1/status/2064277888216555684" target="_blank" rel="noreferrer">https://x.com/sairahul1/status/2064277888216555684</a><br><strong>類型</strong>：Twitter Article<br><strong>統計</strong>：❤️ 801 · 🔁 115 · 🔖 3,030 · 👁 1,218,878</p><hr><h2 id="分析摘要" tabindex="-1">分析摘要 <a class="header-anchor" href="#分析摘要" aria-label="Permalink to &quot;分析摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：以 Token 成本切入的 Loop Engineering 入門，核心主張：DeepSeek 等中國 LLM 讓一般人終於負擔得起 loop 工程（1.7B tokens 只需 $20）。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>成本是真正隱藏壁壘</strong>：&quot;Loops are not hard to design, they are hard to afford&quot;——單一 loop 50K–200K tokens；Fleet loop 500K–2M tokens；最直接的成本分析</li><li><strong>六個構件</strong>（比多數版本多明確列 Memory）：Automations / Worktrees / Skills / Plugins &amp; Connectors / Subagents / Memory</li><li><strong>五部分 loop 結構</strong>：Goal（明確 done 條件）→ Context（VISION.md/ARCHITECTURE.md/RULES.md）→ Action → Feedback（tests/linters）→ Stop condition</li><li><strong>兩種 loop 類型</strong>：Open loop（探索性、高消耗）vs Closed loop（有邊界、可靠、今日即可負擔）</li><li><strong>技能轉移</strong>：Prompt Engineer 追求更好輸出；Loop Engineer 設計產生「驗證結果」的系統</li></ol><h3 id="關鍵技術細節" tabindex="-1">關鍵技術細節 <a class="header-anchor" href="#關鍵技術細節" aria-label="Permalink to &quot;關鍵技術細節&quot;">​</a></h3><ul><li>DeepSeek V4：1M context window、384K max output、高並發（2500 req）、極低 token pricing</li><li>Skills 三文件建議：VISION.md（成功樣貌）、ARCHITECTURE.md（技術棧）、RULES.md（agent 禁止事項）</li><li><code>/goal</code> 底層原理：獨立 fresh model 判斷 done，非執行 agent 自評</li><li>Closed loop 五要素完整框架較 addyosmani 版更具操作性</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>DeepSeek 廣告成分</strong>：「Token 成本問題 → DeepSeek 解方」的文章結構與贊助商內容常見手法相同，需保持距離評估客觀性</li><li><strong>圖片缺失</strong>：大量具體 loop 範例（Coding/Research/Content/Sales loops）均為圖片（16個 entity），fxtwitter API 無法取回，實際範例無法評估</li><li><strong>文末引用問題</strong>：「The loop doesn&#39;t know the difference. You do.」與 addyosmani 文章結語幾乎相同，未標明出處</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>理由</th></tr></thead><tbody><tr><td>A. Workspace 可行動性</td><td>7/10</td><td>Skills 三文件格式（VISION/ARCH/RULES）是新增可行動點</td></tr><tr><td>B. 創新性</td><td>6/10</td><td>與 addyosmani 文章大幅重疊；DeepSeek 成本切入是新角度但廣告性強</td></tr><tr><td>C. 證據品質</td><td>5/10</td><td>Token 成本範圍有量化；但大量內容靠圖片（無法取回）</td></tr><tr><td>D. 技術深度</td><td>6/10</td><td>五部分 loop 結構比 addyosmani 更具操作性；無代碼</td></tr><tr><td>E. 泛化性</td><td>8/10</td><td>Loop 框架通用；成本觀點跨所有 AI workflow</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.40/10</strong></td><td>A×0.3 + B×0.2 + C×0.2 + D×0.15 + E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule<br><strong>整合位置</strong>：<code>subagent-strategy.md</code> 補充 Skills 三文件格式；Token 成本估算可入 finops refs<br><strong>整合狀態</strong>：待實作</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><blockquote><p><strong>注意</strong>：文中多個圖片（loop 範例圖等）fxtwitter API 無法取回，以 [圖片] 標記。</p></blockquote><p>Peter Steinberger, creator of OpenClaw, who now works with OpenAI.</p><p>Yesterday he posted this:</p><blockquote><p>&quot;You shouldn&#39;t be prompting coding agents anymore. You should be designing loops that prompt your agents.&quot;</p></blockquote><p>Then Boris Cherny, head of Claude Code at Anthropic, said the same thing differently:</p><blockquote><p>&quot;I don&#39;t prompt Claude anymore. I have loops running that prompt Claude and figure out what to do. My job is to write loops.&quot;</p></blockquote><p>Two of the most senior AI engineers alive. Same message.</p><p>Most people read it and thought: what does that actually mean?</p><p>I went deep on it.</p><p>Here is everything — broken down simply.</p><p>No jargon. Just the mental model you need.</p><p>Save this. It will change how you think about AI.</p><h2 id="but-first-the-reason-most-people-never-build-loops" tabindex="-1">BUT FIRST: THE REASON MOST PEOPLE NEVER BUILD LOOPS <a class="header-anchor" href="#but-first-the-reason-most-people-never-build-loops" aria-label="Permalink to &quot;BUT FIRST: THE REASON MOST PEOPLE NEVER BUILD LOOPS&quot;">​</a></h2><blockquote><p>Loops sound great. Then you see the bill.</p></blockquote><p>Here is what nobody tells you upfront.</p><p>A single agent loop on a medium coding task: 50,000–200,000 tokens.</p><p>A fleet loop with an orchestrator and 3 specialists: 500,000–2,000,000 tokens.</p><p>A loop running on a schedule every morning: millions of tokens per week.</p><p>At standard API pricing, a week of serious loop engineering costs more than most people&#39;s entire monthly AI budget.</p><p>This is why Peter Steinberger&#39;s replies were full of people saying:</p><blockquote><p>&quot;Easy for you to say — you have unlimited OpenAI access.&quot;</p></blockquote><p>They are not wrong.</p><p>Loop engineering on a normal budget breaks fast.</p><p>Every retry costs. Every self-correction costs. Every subagent costs. Every verification pass costs.</p><p>The open loop that explores freely? Burns tokens at a rate that makes your eyes water.</p><p>This is the hidden blocker nobody talks about.</p><p>Loops are not hard to design.</p><p>They are hard to afford.</p><p>That is exactly what Chinese LLMs solve.</p><p>Models like DeepSeek, Kimi, and MiniMax make agent loops economically viable.</p><p>The biggest problem with autonomous agents is not intelligence.</p><p>It is token burn.</p><p>Loops consume tokens fast.</p><p>A single run can easily burn 50K–200K tokens.</p><p>Run multiple agents, schedule loops daily, or work on large codebases — and costs spiral quickly.</p><p>This is where DeepSeek changes the equation.</p><p>DeepSeek V4 is currently one of the cheapest frontier-level models for running loops at scale.</p><p>What you get:</p><p>→ 1M context window — built for large projects and long-running workflows</p><p>→ 384K max output — handles bigger generations without breaking</p><p>→ DeepSeek V4 Flash + Pro models</p><p>→ Extremely low token pricing</p><p>→ Tool calls + JSON output for agent workflows</p><p>→ High concurrency (up to 2500 requests)</p><p>1.7 billion tokens for $20.</p><p>That is not a typo.</p><p>That is the number that changes the math on loop engineering.</p><p>So let&#39;s talk about loops.</p><h2 id="part-1-what-is-a-loop" tabindex="-1">PART 1: WHAT IS A LOOP? <a class="header-anchor" href="#part-1-what-is-a-loop" aria-label="Permalink to &quot;PART 1: WHAT IS A LOOP?&quot;">​</a></h2><p>A loop is not a single agent call.</p><p>A loop is when the agent keeps going until something is actually true.</p><p>The shortest version:</p><p>→ You define what DONE means</p><p>→ The agent works toward it</p><p>→ A separate part of the system checks if it got there</p><p>→ If not: it tries again</p><p>→ If yes: it stops</p><p>One turn. One attempt. One shot.</p><p>That&#39;s how most people use AI.</p><p>A loop is different.</p><p>→ Write the function</p><p>→ Run the tests</p><p>→ Fix what fails</p><p>→ Run the tests again</p><p>→ Keep going until all tests pass</p><p>That&#39;s a loop.</p><p>Not more prompting. A self-improving cycle.</p><p>[圖片]</p><h2 id="part-2-the-two-kinds-of-loops" tabindex="-1">PART 2: THE TWO KINDS OF LOOPS <a class="header-anchor" href="#part-2-the-two-kinds-of-loops" aria-label="Permalink to &quot;PART 2: THE TWO KINDS OF LOOPS&quot;">​</a></h2><p>Open Loop vs Closed Loop</p><p>Open Loop: The agent explores freely.</p><p>→ No hard stop condition</p><p>→ Powerful, but expensive</p><p>→ Best for research and discovery</p><p>→ Needs near-unlimited token budget</p><p>Closed Loop: The agent runs until a verifiable condition is true.</p><p>→ Tests pass</p><p>→ Lint is clean</p><p>→ Schema matches</p><p>→ PR is open</p><p>→ Ticket is updated</p><p>→ These are not feelings. They are binary checks.</p><p>This is the one that actually works for most people today.</p><p>The open loop is powerful.</p><p>The closed loop is what pays off.</p><p>[圖片]</p><h2 id="part-3-single-agent-vs-fleet" tabindex="-1">PART 3: SINGLE AGENT VS FLEET <a class="header-anchor" href="#part-3-single-agent-vs-fleet" aria-label="Permalink to &quot;PART 3: SINGLE AGENT VS FLEET&quot;">​</a></h2><p>Single Agent Loop</p><p>One brain, self-improving:</p><p>DISCOVER → PLAN → EXECUTE → VERIFY → (loop back if failed)</p><p>Fleet Loop</p><p>Multiple specialists, each running their own loop:</p><p>[圖片]</p><p>Orchestrator gives the goal.</p><p>Specialist agents each run a loop.</p><p>All feed back to the orchestrator.</p><p>Orchestrator decides what&#39;s done — or what loops again.</p><h2 id="part-4-the-5-part-anatomy-of-a-good-loop" tabindex="-1">PART 4: THE 5-PART ANATOMY OF A GOOD LOOP <a class="header-anchor" href="#part-4-the-5-part-anatomy-of-a-good-loop" aria-label="Permalink to &quot;PART 4: THE 5-PART ANATOMY OF A GOOD LOOP&quot;">​</a></h2><p>Every reliable loop has exactly five things:</p><ol><li>GOAL — What done means precisely.</li></ol><p>&quot;All tests in test/auth pass and lint is clean&quot;</p><p>Not &quot;write authentication&quot;. Not &quot;make it work&quot;.</p><p>A condition the system can check — pass or fail, true or false.</p><p>Vague goals create infinite loops.</p><p>Precise goals create reliable ones.</p><ol start="2"><li>CONTEXT — What the agent knows before it starts.</li></ol><p>→ VISION.md — what success looks like</p><p>→ ARCHITECTURE.md — the tech stack and folder structure</p><p>→ RULES.md — what the agent is never allowed to do</p><p>Without context: the loop guesses.</p><p>With context: the loop acts on intent.</p><ol start="3"><li>ACTION — What the agent is actually allowed to do.</li></ol><p>Files it can read. Files it can write. APIs it can call. Commands it can run.</p><p>Narrow the action space. Narrow the failure space.</p><ol start="4"><li>FEEDBACK — How the loop knows if it worked.</li></ol><p>→ Tests that pass or fail</p><p>→ Type errors that surface or don&#39;t</p><p>→ Lint warnings that appear or disappear</p><p>→ Structured errors the agent can read and act on</p><p>Not feelings. Not vibes. Binary signals.</p><ol start="5"><li>STOP CONDITION — When the loop knows it&#39;s finished.</li></ol><p>A separate evaluator — not the agent that did the work — checks the goal condition.</p><p>This is what /goal does under the hood.</p><p>A fresh model decides if you&#39;re done.</p><p>Not the one who wanted to be done.</p><p>[圖片]</p><h2 id="part-5-the-6-things-you-actually-build" tabindex="-1">PART 5: THE 6 THINGS YOU ACTUALLY BUILD <a class="header-anchor" href="#part-5-the-6-things-you-actually-build" aria-label="Permalink to &quot;PART 5: THE 6 THINGS YOU ACTUALLY BUILD&quot;">​</a></h2><ol><li>AUTOMATIONS</li></ol><p>This is the heartbeat.</p><p>Automations trigger discovery and triage by themselves.</p><p>→ Claude Code: /loop, /schedule, hooks, GitHub Actions</p><p>→ Codex: Automations tab — pick project, prompt, cadence</p><p>Daily loop examples from real teams:</p><p>→ Scan CI failures and write summaries</p><p>→ Triage open issues by severity</p><p>→ Hunt bugs added in the last 24 hours</p><p>→ Write commit briefings for the team</p><p>Without automations: you are the trigger.</p><p>With automations: the system surfaces the work.</p><ol start="2"><li>WORKTREES</li></ol><p>This is what prevents chaos when you run parallel agents.</p><p>Two agents writing the same file is the same headache as two engineers committing to the same lines without talking.</p><p>A git worktree is a separate working directory on its own branch — sharing the same repo history.</p><p>One agent&#39;s edits cannot touch the other&#39;s checkout.</p><p>→ Claude Code: --worktree flag, isolation: worktree on subagents</p><p>→ Codex: worktree support built in</p><p>Your review bandwidth is still the ceiling.</p><p>Worktrees remove the collision.</p><p>You remove the bottleneck.</p><ol start="3"><li>SKILLS</li></ol><p>This is how you stop re-explaining your project every single time.</p><p>Both tools use the same format: a folder with a SKILL.md inside — plus optional scripts, references, assets.</p><p>Without skills: the loop re-derives your whole project from zero every cycle.</p><p>With skills: it compounds. The agent knows your project before it starts.</p><p>→ VISION.md — what success looks like</p><p>→ ARCHITECTURE.md — the tech stack and folder structure</p><p>→ RULES.md — what the agent is never allowed to do</p><ol start="4"><li>PLUGINS AND CONNECTORS</li></ol><p>This is what makes EXECUTE real — the loop acts in your actual environment, not just your filesystem.</p><p>A loop that can only see the filesystem is a tiny loop.</p><p>Connectors (built on MCP) let the agent read your issue tracker, query a database, hit a staging API, drop a message in Slack.</p><p>This is the difference between an agent that says &quot;here is the fix&quot; and a loop that opens the PR, links the Linear ticket, and pings the channel once CI is green — by itself.</p><ol start="5"><li>SUBAGENTS</li></ol><p>This is what makes VERIFY honest — the checker is never the same agent as the maker.</p><p>Keep the maker away from the checker.</p><p>The model that wrote the code is too nice grading its own homework.</p><p>A second agent with different instructions — sometimes a different model — catches the stuff the first one talked itself into.</p><p>The split that works:</p><p>→ One agent explores</p><p>→ One agent implements</p><p>→ One agent verifies against the spec</p><p>This is also what /goal does under the hood.</p><p>A fresh model decides if the loop is done — not the one that did the work.</p><ol start="6"><li>MEMORY</li></ol><p>This is what makes the loop persistent — DISCOVER on run 47 knows everything runs 1 through 46 already tried.</p><p>The spine of the whole loop.</p><p>A markdown file. A Linear board. Anything that lives outside the single conversation.</p><p>The model forgets everything between runs.</p><p>The repo does not.</p><p>The memory file holds: what got tried, what passed, what is still open.</p><p>Tomorrow morning the loop picks up where today stopped.</p><p>It sounds too simple to matter.</p><p>Every long-running loop depends on it.</p><h2 id="part-6-real-loop-examples" tabindex="-1">PART 6: REAL LOOP EXAMPLES <a class="header-anchor" href="#part-6-real-loop-examples" aria-label="Permalink to &quot;PART 6: REAL LOOP EXAMPLES&quot;">​</a></h2><p>[圖片 — Coding Loop]</p><p>[圖片 — Research Loop]</p><p>[圖片 — Content Loop]</p><p>[圖片 — Sales Outreach Loop]</p><p>Every loop has the same skeleton:</p><p>Goal → Action → Check → Fix → Repeat until done.</p><h2 id="part-7-prompt-engineer-vs-loop-engineer" tabindex="-1">PART 7: PROMPT ENGINEER VS LOOP ENGINEER <a class="header-anchor" href="#part-7-prompt-engineer-vs-loop-engineer" aria-label="Permalink to &quot;PART 7: PROMPT ENGINEER VS LOOP ENGINEER&quot;">​</a></h2><p>Prompt Engineer:</p><p>→ Craft better instructions → Linguistic skill → Better prompt → better single output → Still reviews output manually after every run → You are the feedback loop</p><p>Loop Engineer:</p><p>→ Design better feedback cycles → Software engineering skill → Better loop → reliable verified outcomes → System runs, checks, and self-corrects → The system is the feedback loop</p><p>The tools are the same. The mindset is completely different.</p><p>Prompt engineers ask AI for output.</p><p>Loop engineers design systems that produce verified outcomes.</p><p>The highest-paid AI engineers in 2026 are not writing better English sentences.</p><p>They are writing the logic that governs how agents discover, plan, check their own work, and know when they are done.</p><h2 id="closing" tabindex="-1">CLOSING <a class="header-anchor" href="#closing" aria-label="Permalink to &quot;CLOSING&quot;">​</a></h2><p>The shift:</p><p>→ For two years we prompted agents one task at a time → Now we design loops that run the whole cycle</p><p>The 6 things you actually build: Automations / Worktrees / Skills / Plugins and connectors / Subagents / Memory</p><p>Two scales: Single agent (one brain, self-improving) / Fleet (orchestrator + specialists + subagents)</p><p>Two types: Open loop (exploratory, powerful, expensive) / Closed loop (bounded, reliable, affordable)</p><p>The 5 parts of every good loop: Goal / Context / Action / Feedback / Stop condition</p><p>The cost problem: Loops burn tokens fast. $20 on DeepSeek goes dramatically further than most frontier models.</p><p>Peter Steinberger said it right:</p><p>Stop prompting your agents. Start designing loops.</p><p>Because one reliable loop is worth a thousand perfect prompts.</p><p>Two people can build the exact same loop and get completely opposite results.</p><p>One uses it to move faster on work they understand deeply.</p><p>The other uses it to avoid understanding the work at all.</p><p>The loop does not know the difference. You do.</p><p>Build the loop. But build it like someone who intends to stay the engineer — not just the person who presses go.</p><p>Because one reliable loop is worth a thousand perfect prompts.</p><p>And with 1.7 billion tokens for $20, you can finally afford to build one.</p>',235)])])}const g=t(p,[["render",n]]);export{c as __pageData,g as default};
